const ALL = ["CoinGecko", "Coinpaprika", "DefiLlama", "Frankfurter", "CurrencyAPI", "Econdb", "Helious", "FuturesClock", "TheCalendar", "SEC_EDGAR", "OpenMeteo", "Noozra"];
const body = $json.body || $json || {};
let sources = body.sources !== undefined ? body.sources : (body.source || 'all');
if (sources === 'all' || sources === true || sources == null) sources = ALL.slice();
else if (typeof sources === 'string') sources = sources.split(',').map(s => s.trim()).filter(Boolean);
else if (!Array.isArray(sources)) sources = ALL.slice();
sources = sources.filter(s => ALL.includes(s));
if (!sources.length) sources = ALL.slice();
return [{ json: { sources, requested_at: new Date().toISOString(), mode: 'phase1-public' } }];

const name = 'CoinGecko';
let j = $input.first().json;
function trim(v){
  if (Array.isArray(v)) return {truncated:true, count:v.length, sample:v.slice(0,8)};
  if (v && typeof v==='object'){
    const keys=Object.keys(v);
    if (keys.length>30){
      const s={};
      for (const k of keys.slice(0,20)) {
        const val=v[k];
        s[k]= (typeof val==='object'&&val&&!Array.isArray(val)) ? '{…}' : (Array.isArray(val)?`[${val.length}]`:val);
      }
      return {truncated:true,key_count:keys.length,sample:s};
    }
    const out={};
    for (const k of keys){
      const val=v[k];
      if (Array.isArray(val)) out[k]={count:val.length,sample:val.slice(0,5)};
      else out[k]=val;
    }
    return out;
  }
  return v;
}
const ok = !(j && (j.error || j.message) && (j.statusCode || j.status || j.error));
return [{json:{source:name, ok:ok, data:trim(j)}}];

