const ALL = ["CoinGecko", "Coinpaprika", "DefiLlama", "Frankfurter", "CurrencyAPI", "Econdb", "Helious", "FuturesClock", "TheCalendar", "SEC_EDGAR", "OpenMeteo", "Noozra"];
const requested = ($('Normalize Sources').first().json.sources) || ALL;
const out = { ok: true, phase: 1, oom_fix: true, requested_at: $('Normalize Sources').first().json.requested_at,
  sources_requested: requested, results: {}, errors: {} };
for (const name of ALL) {
  if (!requested.includes(name)) { out.results[name] = { skipped: true }; continue; }
  try {
    const item = $(name).first(); const j = item ? item.json : null;
    if (!j) { out.results[name] = { error: true }; out.errors[name] = { message: 'no data' }; continue; }
    if (j.ok === false || (j.data && (j.data.error || j.data.message) && (j.data.statusCode || j.data.status || j.data.error))) {
      const d = j.data || j;
      out.errors[name] = { message: d.message || d.error || 'request failed', status: d.statusCode || d.status };
      out.results[name] = { error: true };
    } else {
      out.results[name] = j.data !== undefined ? j.data : j;
    }
  } catch (e) {
    out.errors[name] = { message: String(e.message || e) };
    out.results[name] = { error: true };
  }
}
return [{ json: out }];

const res = $input.first().json.results || {};
const items = [];

// 1. CoinGecko crypto sentiment
const cg = res.CoinGecko;
if (cg && !cg.skipped && !cg.error) {
  const map = [
    { key: 'bitcoin', symbol: 'BTCUSDT' },
    { key: 'ethereum', symbol: 'ETHUSDT' },
    { key: 'solana', symbol: 'SOLUSDT' }
  ];
  for (const m of map) {
    const d = cg[m.key];
    if (d && typeof d.usd_24h_change === 'number') {
      const chg = d.usd_24h_change;
      const score = Math.max(-1, Math.min(1, chg / 5.0));
      items.push({
        json: {
          type: 'sentiment',
          endpoint: 'http://backend:8000/api/news/sentiment',
          payload: {
            symbol: m.symbol,
            sentiment_score: Math.round(score * 100) / 100,
            impact_score: 0.6,
            source: 'coingecko',
            time_horizon: 'short',
            topics: 'crypto,macro_scan'
          }
        }
      });
    }
  }
}

// 2. Frankfurter FX rates
const ff = res.Frankfurter;
if (ff && !ff.skipped && !ff.error && ff.rates) {
  const rates = ff.rates;
  const events = [];
  for (const [curr, rate] of Object.entries(rates)) {
    events.push({
      time_utc: new Date().toISOString(),
      currency: curr,
      impact: 'LOW',
      title: `USD/${curr} Reference Rate: ${rate}`,
      forecast: String(rate),
      previous: '',
      source: 'frankfurter'
    });
  }
  if (events.length > 0) {
    items.push({
      json: {
        type: 'calendar',
        endpoint: 'http://backend:8000/api/calendar/batch',
        payload: { events }
      }
    });
  }
}

return items.length > 0 ? items : [{ json: { type: 'empty' } }];
